13	/// MCP content-block annotations (JavaScript-friendly). Currently carries
14	/// only `audience` — michi has no concept of MCP's optional `priority`.
15	#[napi(object, js_name = "Annotations")]
16	#[derive(Debug, Clone)]
17	pub struct JsAnnotations {
18	    /// `["assistant"]` or `["user"]` — which surface(s) this block targets.
19	    pub audience: Vec<String>,
20	}
