22	/// One MCP content block (JavaScript-friendly). Wire-conformant with MCP's
23	/// text content shape: `{type: "text", text, annotations: {audience: [...]}}`.
24	#[napi(object, js_name = "ContentBlock")]
25	#[derive(Debug, Clone)]
26	pub struct JsContentBlock {
