36	/// The MCP `CallToolResult` shape, returned by `AgentResponse.toCallToolResult`.
37	#[napi(object, js_name = "CallToolResult")]
38	#[derive(Debug, Clone)]
39	pub struct JsCallToolResult {
40	    /// Text content blocks.
41	    pub content: Vec<JsContentBlock>,
