52	/// Bytes charged to a response's total for each section beyond its strings: roughly the size of the `Section` itself.
53	const SECTION_OVERHEAD: usize = 64;
54	
55	/// Bytes charged for an error beyond its message and causes: the code, the struct, and the verify-first hint a
56	/// timeout carries.
57	const ERROR_OVERHEAD: usize = 256;
58	
59	/// String bytes one [`JsAgentResponse`] holds, per slot. A slot that a call replaces (`truncationHint`,
60	/// `humanContent`, `error`) gives its old bytes back; `items`, `kvItems`, `hint`, `recoveryHint` and the outcome
61	/// sections (`partialSuccess`, `pipeline`, `status`, `alreadyDone`) each add a block, so they only add.
62	#[derive(Debug, Default)]
63	struct HeldBytes {
64	    type_name: usize,
65	    items: usize,
66	    kv_items: usize,
67	    hints: usize,
68	    recovery: usize,
69	    truncation_hint: usize,
70	    human_content: usize,
71	    error: usize,
72	    outcomes: usize,
73	}
74	
75	impl HeldBytes {
76	    fn total(&self) -> usize {
77	        [
78	            self.type_name,
79	            self.items,
80	            self.kv_items,
81	            self.hints,
82	            self.recovery,
83	            self.truncation_hint,
84	            self.human_content,
85	            self.error,
86	            self.outcomes,
87	        ]
88	        .iter()
89	        .fold(0, |acc, n| acc.saturating_add(*n))
90	    }
91	
92	    /// An error if replacing a slot holding `old` bytes with `new` would take the total past
93	    /// [`input::MAX_INPUT_BYTES`]. Changes nothing: the caller stores the new slot size once its call succeeds.
94	    fn check_replace(&self, old: usize, new: usize) -> napi::Result<()> {
95	        let total = self.total().saturating_sub(old).saturating_add(new);
96	        if total > input::MAX_INPUT_BYTES {
97	            return Err(napi::Error::from_reason(format!(
98	                "cumulative byte total {total} exceeds maximum of {}",
99	                input::MAX_INPUT_BYTES
100	            )));
101	        }
102	        Ok(())
103	    }
104	}
105	
106	/// What one row costs beyond its cells: the row vector. `Array(100000).fill([])` has no cells and still keeps
107	/// 100,000 of these.
108	const ROW_OVERHEAD: usize = std::mem::size_of::<Vec<crate::toon::Value>>();
109	
110	/// What one field name costs: its string and the `String` that holds it.
111	fn field_cost(f: &str) -> usize {
112	    std::mem::size_of::<String>().saturating_add(f.len())
113	}
114	
115	/// What one row of a four-column outcome table (`partialSuccess`, `pipeline`, `status`) keeps beyond its strings.
116	const OUTCOME_ROW: usize = ROW_OVERHEAD + 4 * std::mem::size_of::<crate::toon::Value>();
117	
118	/// What a named outcome section costs before its rows: its name, which is written in its header and again in the
119	/// `totalCount` table, and the section itself.
120	fn outcome_section_cost(name: &str) -> usize {
121	    field_cost(name).saturating_add(name.len()).saturating_add(SECTION_OVERHEAD)
122	}
123	
124	/// The sum of `costs`, saturating.
125	fn sum(costs: impl IntoIterator<Item = usize>) -> usize {
126	    costs.into_iter().fold(0, usize::saturating_add)
127	}
