129	/// NAPI wrapper around [`crate::response::AgentResponse`].
130	///
131	/// Besides each call's own limits, one object holds at most 16 MiB across all its calls: caller strings (type name,
132	/// fields, cells, keys, hints, recovery hints, truncation hint and human content) plus the storage rows and cells
133	/// keep, so a table of empty rows, numbers or nulls is charged too. A call that would pass that total
134	/// is rejected and leaves the builder unchanged; replacing `truncationHint` or `humanContent` gives the old value's
135	/// bytes back first. Every `items` and `kvItems` call adds a section, so their bytes add up; each section is also
136	/// charged the type name's bytes plus 64, so empty calls are not free.
137	///
138	/// The total bounds the output too: a render is at most 19 times the bytes held, plus 4 KiB, on every surface (text,
139	/// JSON, `toCallToolResult`), under V8's string limit; see [`input::MAX_INPUT_BYTES`]. Control characters, which
140	/// escape to six bytes in the text and again in the JSON, are the worst case for a string. A name can be written
141	/// more often than a string, so each is charged for every place it can be written: a field name, and the type name
142	/// or an outcome section's name, once for every cell of the table that is longer than 200 chars (a `truncated` row
143	/// repeats them for every cut cell), a section's name twice (its header and the `totalCount` table), and each hint
144	/// and recovery hint a few bytes for the row or object that holds it.
145	///
146	/// Both methods name their section for the type name, and a section is a root key in the rendered document. Two
147	/// `items` calls, or a `kvItems` key equal to the type name, therefore render the `toon_validation_failed` error
148	/// (`isError` true) instead of invalid TOON. The JS surface renders one list per response.
149	#[napi(js_name = "AgentResponse")]
150	#[derive(Debug)]
151	pub struct JsAgentResponse {
152	    inner: Option<crate::response::AgentResponse>,
153	    /// The type name, which names the sections `items` and `kvItems` append.
154	    name: String,
155	    /// Cumulative count of [`Self::hint`] calls, capped at [`MAX_HINTS`].
156	    hint_count: usize,
157	    /// Cumulative count of [`Self::recovery_hint`] calls, capped at [`MAX_HINTS`].
158	    recovery_count: usize,
159	    /// String bytes held, capped at [`input::MAX_INPUT_BYTES`] in all.
160	    held: HeldBytes,
161	}
162	
163	impl JsAgentResponse {
164	    /// What every section costs before its own strings: a copy of the type name, which names it, plus a fixed
165	    /// allowance for the section itself. Without it an empty `items` or `kvItems` call would be free, and a loop of
166	    /// them would grow the response past the cap.
167	    ///
168	    /// A list writes its name in its header and again in the `totalCount` table, a KV section only in the table, and
169	    /// each also writes it once in the JSON `sections`. That is two writes of the name per section, and the name is
170	    /// charged twice: here, and once when the response is built (`HeldBytes::type_name`). Only one list can carry the
171	    /// type name, since a second is a root-key collision that replaces the body with a short error, and every KV
172	    /// section writes it at most once in the body.
173	    fn section_cost(&self) -> usize {
174	        self.name.len().saturating_add(SECTION_OVERHEAD)
175	    }
176	
177	    fn take(&mut self) -> napi::Result<crate::response::AgentResponse> {
178	        self.inner.take().ok_or_else(consumed)
179	    }
180	
181	    fn built(&self) -> napi::Result<&crate::response::AgentResponse> {
182	        self.inner.as_ref().ok_or_else(consumed)
183	    }
184	
185	    /// Append a TOON list section. The caller has bounded `rows`, `fields` and every row's length (see
186	    /// [`Self::items`]); this charges the bytes they keep, then converts, so the builder is unchanged on error.
187	    fn add_items(
188	        &mut self,
189	        rows: Vec<Vec<JsToonValue>>,
190	        fields: Vec<String>,
191	        total_count: Option<JsCount>,
192	    ) -> napi::Result<()> {
193	        let bytes = fields
194	            .iter()
195	            .map(|f| field_cost(f.as_str()))
196	            .chain(rows.iter().map(|row| row.iter().map(cell_cost).fold(ROW_OVERHEAD, usize::saturating_add)))
197	            .chain([cost::table_repeats(&rows, &fields, self.name.len())])
198	            .fold(self.section_cost(), usize::saturating_add);
199	        self.held.check_replace(0, bytes)?;
200	        let converted: Vec<Vec<crate::toon::Value>> = rows
201	            .into_iter()
202	            .map(|row| row.into_iter().map(|v| Ok(v.into_cell()?.into())).collect::<napi::Result<Vec<_>>>())
203	            .collect::<napi::Result<Vec<_>>>()?;
204	        let b = self.take()?;
205	        let section = crate::section::Section::toon(self.name.clone(), fields, converted)
206	            .total_count(total_count.map(JsCount::get));
207	        self.inner = Some(b.section(section));
208	        self.held.items = self.held.items.saturating_add(bytes);
209	        Ok(())
210	    }
211	
212	    /// Append a KV section: the same accounting as [`Self::add_items`].
213	    fn add_kv_items(&mut self, items: Vec<JsKvItem>, total_count: Option<JsCount>) -> napi::Result<()> {
214	        let bytes = items
215	            .iter()
216	            .map(|i| std::mem::size_of::<String>().saturating_add(i.key.len()).saturating_add(cell_cost(&i.value)))
217	            .fold(self.section_cost(), usize::saturating_add);
218	        self.held.check_replace(0, bytes)?;
219	        let converted = items
220	            .into_iter()
221	            .map(|i| Ok(crate::kv::KvItem::new(i.key, i.value.into_cell()?.into())))
222	            .collect::<napi::Result<Vec<_>>>()?;
223	        let b = self.take()?;
224	        let section =
225	            crate::section::Section::kv(self.name.clone(), converted).total_count(total_count.map(JsCount::get));
226	        self.inner = Some(b.section(section));
227	        self.held.kv_items = self.held.kv_items.saturating_add(bytes);
228	        Ok(())
229	    }
230	
231	    /// Charge `bytes` to the outcome slot, then apply `add` to the builder. The builder is unchanged on error.
232	    fn add_outcome(
233	        &mut self,
234	        bytes: usize,
235	        add: impl FnOnce(crate::response::AgentResponse) -> crate::response::AgentResponse,
236	    ) -> napi::Result<()> {
237	        self.held.check_replace(0, bytes)?;
238	        let b = self.take()?;
239	        self.inner = Some(add(b));
240	        self.held.outcomes = self.held.outcomes.saturating_add(bytes);
241	        Ok(())
242	    }
243	
244	    /// Set the error block; see [`Self::error`].
245	    fn set_error(
246	        &mut self,
247	        code: &str,
248	        message: String,
249	        causes: Vec<String>,
250	        retryable: Option<bool>,
251	    ) -> napi::Result<()> {
252	        // A cause is written like a hint (its text plus a quote or separator per surface), so it is charged like one.
253	        // Charging the `String` that holds it as well cut the capacity of one error report below what the per-call
254	        // string cap allows.
255	        let bytes = sum(causes
256	            .iter()
257	            .map(|c| c.len().saturating_add(cost::HINT_OVERHEAD))
258	            .chain([message.len(), ERROR_OVERHEAD]));
259	        self.held.check_replace(self.held.error, bytes)?;
260	        let mut err = super::outcome::build_domain_error(code, message, causes)?;
261	        if let Some(retryable) = retryable {
262	            err = err.retryable(retryable);
263	        }
264	        let b = self.take()?;
265	        self.inner = Some(b.error(err));
266	        self.held.error = bytes;
267	        Ok(())
268	    }
269	
270	    /// Append the per-operation outcomes table; see [`Self::partial_success`].
271	    fn add_partial_success(
272	        &mut self,
273	        name: String,
274	        completed: Vec<JsCompletedOp>,
275	        failed: Vec<JsFailedOp>,
276	        skipped: Vec<JsSkippedOp>,
277	    ) -> napi::Result<()> {
278	        let rows = completed.len() + failed.len() + skipped.len();
279	        let strings = sum(completed
280	            .iter()
281	            .map(|o| o.operation.len())
282	            .chain(failed.iter().map(|o| {
283	                let recovery = o
284	                    .recovery
285	                    .as_ref()
286	                    .map_or(0, |r| SECTION_OVERHEAD + r.tool.len() + r.reason.as_ref().map_or(0, String::len));
287	                o.operation.len() + o.reason.len() + recovery
288	            }))
289	            .chain(skipped.iter().map(|o| o.operation.len() + o.reason.as_ref().map_or(0, String::len))));
290	        let cut = cost::cut_count(
291	            completed
292	                .iter()
293	                .map(|o| o.operation.as_str())
294	                .chain(failed.iter().flat_map(|o| [o.operation.as_str(), o.reason.as_str()]))
295	                .chain(skipped.iter().flat_map(|o| [o.operation.as_str(), o.reason.as_deref().unwrap_or("")])),
296	        );
297	        let repeats = cost::fixed_table_repeats(cut, name.len());
298	        let bytes = sum([outcome_section_cost(&name), strings, rows.saturating_mul(OUTCOME_ROW), repeats]);
299	        let outcome = super::outcome::build_partial_success(completed, failed, skipped)?;
300	        self.add_outcome(bytes, |b| b.partial_success(name, outcome))
301	    }
302	
303	    /// Append the pipeline table; see [`Self::pipeline`].
304	    fn add_pipeline(&mut self, name: String, steps: Vec<JsPipelineStep>) -> napi::Result<()> {
305	        let strings = sum(steps.iter().map(|s| s.id.len() + s.name.len()));
306	        let cut = cost::cut_count(steps.iter().flat_map(|s| [s.id.as_str(), s.name.as_str()]));
307	        let repeats = cost::fixed_table_repeats(cut, name.len());
308	        let bytes = sum([outcome_section_cost(&name), strings, steps.len().saturating_mul(OUTCOME_ROW), repeats]);
309	        let pipeline = super::outcome::build_pipeline(steps)?;
310	        self.add_outcome(bytes, |b| b.pipeline(name, pipeline))
311	    }
312	
313	    /// Append the status sections; see [`Self::status`].
314	    fn add_status(&mut self, tool_name: String, description: String, items: Vec<JsStatusItem>) -> napi::Result<()> {
315	        let strings =
316	            sum(items.iter().map(|i| i.key.len() + cell_cost(&i.value) + i.health.as_ref().map_or(0, String::len)));
317	        let head = sum([tool_name.len(), description.len(), 2 * SECTION_OVERHEAD]);
318	        let cut = cost::cut_count(items.iter().flat_map(|i| {
319	            [i.key.as_str(), i.value.str_val.as_deref().unwrap_or(""), i.health.as_deref().unwrap_or("")]
320	        }));
321	        let repeats = cost::fixed_table_repeats(cut, "items".len());
322	        let bytes = sum([head, strings, items.len().saturating_mul(OUTCOME_ROW), repeats]);
323	        let status = super::toon::build_status(tool_name, description, items)?;
324	        self.add_outcome(bytes, |b| b.status(status))
325	    }
326	
327	    /// Append the already-done section; see [`Self::already_done`].
328	    fn add_already_done(&mut self, operation: String, summary: String) -> napi::Result<()> {
329	        let bytes = sum([operation.len(), summary.len(), outcome_section_cost("already_done"), 3 * OUTCOME_ROW]);
330	        self.add_outcome(bytes, |b| b.already_done(operation, summary))
331	    }
332	}
333	
334	fn consumed() -> napi::Error {
335	    napi::Error::from_reason("AgentResponse already consumed")
336	}
337	
338	#[napi]
339	impl JsAgentResponse {
340	    /// Create a new response builder for the given type name, `new AgentResponse(typeName)`.
341	    ///
342	    /// # Errors
343	    ///
344	    /// Rejects a `typeName` over 4 KiB.
345	    #[napi(constructor, catch_unwind)]
346	    pub fn new(type_name: String) -> napi::Result<Self> {
347	        input::check_bytes("typeName", &type_name, MAX_NAME_BYTES)?;
348	        let held = HeldBytes { type_name: type_name.len(), ..HeldBytes::default() };
349	        let inner = Some(crate::response::AgentResponse::new(type_name.clone()));
350	        Ok(Self { inner, name: type_name, hint_count: 0, recovery_count: 0, held })
351	    }
352	
353	    /// Append a TOON list section named for the response's type. Every call adds a section, rendered in call order;
354	    /// a second `items` call repeats the root key and renders the validation error (see the type docs).
355	    /// `totalCount`, when given, is how many rows existed before any cut; `totalCount: n` renders only when `n` is
356	    /// larger than the rows passed.
357	    ///
358	    /// # Errors
359	    ///
360	    /// Rejects, before converting anything, more than 100,000 rows, 1,000 fields or 1,000 values in a row, and
361	    /// more than 1,000,000 cells in all; while converting, a field name over 4 KiB, a cell over 1 MiB, more than
362	    /// 16 MiB of strings in the call, or an invalid cell; a `totalCount` that is not a finite, non-negative integer;
363	    /// then strings that would take the response past its 16 MiB total. The builder is unchanged on error.
364	    #[napi(
365	        ts_args_type = "rows: Array<Array<ToonValue>>, fields: Array<string>, totalCount?: number | null",
366	        catch_unwind
367	    )]
368	    pub fn items(&mut self, rows: Unknown<'_>, fields: Unknown<'_>, total_count: Option<JsCount>) -> napi::Result<()> {
369	        let mut budget = Budget::new();
370	        let rows = List::new(rows, "rows")?;
371	        let fields = List::new(fields, "fields")?;
372	        input::check_len("rows", rows.len(), MAX_ROWS)?;
373	        input::check_len("fields", fields.len(), MAX_FIELDS)?;
374	        let fields = budget.strings(&fields, "fields", MAX_FIELDS, "field name", MAX_NAME_BYTES)?;
375	        let rows = budget.rows(&rows, MAX_ROWS, MAX_FIELDS, "maximum")?;
376	        self.add_items(rows, fields, total_count)
377	    }
378	
379	    /// Append a KV section named for the response's type; the name is not printed. Every call adds a section,
380	    /// rendered in call order. `totalCount` works as in [`Self::items`].
381	    ///
382	    /// # Errors
383	    ///
384	    /// Rejects more than 1,000 items before converting any, a key over 4 KiB, a value over 1 MiB, more than 16 MiB
385	    /// of strings in the call, an invalid value, a `totalCount` that is not a finite, non-negative integer, or
386	    /// strings that would take the response past its 16 MiB total. The builder is unchanged on error.
387	    #[napi(js_name = "kvItems", ts_args_type = "items: Array<KvItem>, totalCount?: number | null", catch_unwind)]
388	    pub fn kv_items(&mut self, items: Unknown<'_>, total_count: Option<JsCount>) -> napi::Result<()> {
389	        let mut budget = Budget::new();
390	        let items = List::new(items, "items")?;
391	        let items = budget.kv_items(&items, MAX_FIELDS)?;
392	        self.add_kv_items(items, total_count)
393	    }
394	
395	    /// Report a classified error: it renders first, as `error: <code>`, `message`, `causes[N]` and `exit_code: 1`, and
396	    /// the response is an error on every surface. In `renderJson()` and `structuredContent` it is the object
397	    /// `error: {code, message, causes, retryable}`, beside the response's `hints` and `recovery` arrays (add those
398	    /// with `hint()` and `recoveryHint()`). `retryable` defaults to the code's (true for `rate_limited` and
399	    /// `unavailable`); a `timeout` that is not retryable gets michi's verify-first hint. One per response: a second
400	    /// call replaces it.
401	    ///
402	    /// # Errors
403	    ///
404	    /// Rejects an unknown `code`, a `code` over 4 KiB, a `message` or cause over 1 MiB, more than 10,000 causes, more
405	    /// than 16 MiB of strings in the call, or an error that would take the response past its 16 MiB total. The
406	    /// builder is unchanged on error.
407	    #[napi(
408	        catch_unwind,
409	        ts_args_type = "code: 'invalid_input' | 'not_found' | 'unauthorized' | 'forbidden' | 'conflict' | 'rate_limited' \
410	                        | 'unavailable' | 'timeout' | 'external_failure', message: string, \
411	                        causes?: Array<string> | undefined | null, retryable?: boolean | undefined | null"
412	    )]
413	    pub fn error(
414	        &mut self,
415	        code: Unknown<'_>,
416	        message: Unknown<'_>,
417	        causes: Option<Unknown<'_>>,
418	        retryable: Option<bool>,
419	    ) -> napi::Result<()> {
420	        let mut budget = Budget::new();
421	        let causes = List::optional(causes, "causes")?;
422	        if let Some(causes) = &causes {
423	            input::check_len("causes", causes.len(), MAX_HINTS)?;
424	        }
425	        let code = budget.string(code, "code", MAX_NAME_BYTES)?;
426	        let message = budget.string(message, "message", MAX_STRING_BYTES)?;
427	        let causes = match &causes {
428	            Some(causes) => budget.strings(causes, "causes", MAX_HINTS, "cause", MAX_STRING_BYTES)?,
429	            None => Vec::new(),
430	        };
431	        self.set_error(&code, message, causes, retryable)
432	    }
433	
434	    /// Append a batch's per-operation outcomes as the list section `name`: `name[N]{index,operation,status,reason}:`,
435	    /// a row per operation sorted by `index`. The failed operations' recovery hints join the response's `recovery`.
436	    /// A partial batch is not an error: call `error()` or `asError()` when the call failed as a whole.
437	    ///
438	    /// # Errors
439	    ///
440	    /// Rejects an `index` that appears more than once across the three lists, a completed operation with a `reason`,
441	    /// more than 10,000 entries in a list, a `name`, `operation`, skipped `reason` or recovery `tool` over 4 KiB, a
442	    /// failed `reason` over 1 MiB, an `index` that is not an integer in `0..=2^53-1`, more than 16 MiB of strings in
443	    /// the call, or entries that would take the response past its 16 MiB total. The builder is unchanged on error.
444	    #[napi(
445	        catch_unwind,
446	        ts_args_type = "name: string, completed: Array<CompletedOp>, failed: Array<FailedOp>, skipped: Array<SkippedOp>"
447	    )]
448	    pub fn partial_success(
449	        &mut self,
450	        name: Unknown<'_>,
451	        completed: Unknown<'_>,
452	        failed: Unknown<'_>,
453	        skipped: Unknown<'_>,
454	    ) -> napi::Result<()> {
455	        let mut budget = Budget::new();
456	        let completed = List::new(completed, "completed")?;
457	        let failed = List::new(failed, "failed")?;
458	        let skipped = List::new(skipped, "skipped")?;
459	        input::check_len("completed", completed.len(), MAX_STEPS)?;
460	        input::check_len("failed", failed.len(), MAX_STEPS)?;
461	        input::check_len("skipped", skipped.len(), MAX_STEPS)?;
462	        let name = budget.string(name, "name", MAX_NAME_BYTES)?;
463	        let completed = budget.completed_ops(&completed, MAX_STEPS)?;
464	        let failed = budget.failed_ops(&failed, MAX_STEPS)?;
465	        let skipped = budget.skipped_ops(&skipped, MAX_STEPS)?;
466	        self.add_partial_success(name, completed, failed, skipped)
467	    }
468	
469	    /// Append pipeline state as the list section `name`: `name[N]{id,name,status,reason}:`, a row per step.
470	    ///
471	    /// # Errors
472	    ///
473	    /// Rejects an unknown `status`, a missing or unknown `reason` for `outcome_unknown`, `skipped` or `not_run`, a
474	    /// `reason` on any other status, more than 10,000 steps, a `name`, `id`, `status` or `reason` over 4 KiB, a step
475	    /// `name` over 1 MiB, more than 16 MiB of strings in the call, or steps that would take the response past its
476	    /// 16 MiB total. The builder is unchanged on error.
477	    #[napi(catch_unwind, ts_args_type = "name: string, steps: Array<PipelineStep>")]
478	    pub fn pipeline(&mut self, name: Unknown<'_>, steps: Unknown<'_>) -> napi::Result<()> {
479	        let mut budget = Budget::new();
480	        let steps = List::new(steps, "steps")?;
481	        input::check_len("steps", steps.len(), MAX_STEPS)?;
482	        let name = budget.string(name, "name", MAX_NAME_BYTES)?;
483	        let steps = budget.pipeline_steps(&steps, MAX_STEPS)?;
484	        self.add_pipeline(name, steps)
485	    }
486	
487	    /// Append a status report: `tool` and `description` lines, then `items[N]{key,value,health,reason}:`. An item
488	    /// without `health` renders `ok`. Add hints with `hint()`.
489	    ///
490	    /// # Errors
491	    ///
492	    /// Rejects an unknown `health`, more than 1,000 items, a `toolName` or key over 4 KiB, a `description`, value or
493	    /// `health` over 1 MiB, more than 16 MiB of strings in the call, or items that would take the response past its
494	    /// 16 MiB total. The builder is unchanged on error.
495	    #[napi(catch_unwind, ts_args_type = "toolName: string, description: string, items: Array<StatusItem>")]
496	    pub fn status(&mut self, tool_name: Unknown<'_>, description: Unknown<'_>, items: Unknown<'_>) -> napi::Result<()> {
497	        let mut budget = Budget::new();
498	        let items = List::new(items, "items")?;
499	        input::check_len("items", items.len(), MAX_FIELDS)?;
500	        let tool_name = budget.string(tool_name, "toolName", MAX_NAME_BYTES)?;
501	        let description = budget.string(description, "description", MAX_STRING_BYTES)?;
502	        let items = budget.status_items(&items, MAX_FIELDS)?;
503	        self.add_status(tool_name, description, items)
504	    }
505	
506	    /// Append an already-done report: `operation`, `status: already_done` and `summary` lines.
507	    ///
508	    /// # Errors
509	    ///
510	    /// Rejects an `operation` over 4 KiB, a `summary` over 1 MiB, or text that would take the response past its
511	    /// 16 MiB total. The builder is unchanged on error.
512	    #[napi(catch_unwind, ts_args_type = "operation: string, summary: string")]
513	    pub fn already_done(&mut self, operation: Unknown<'_>, summary: Unknown<'_>) -> napi::Result<()> {
514	        let mut budget = Budget::new();
515	        let operation = budget.string(operation, "operation", MAX_NAME_BYTES)?;
516	        let summary = budget.string(summary, "summary", MAX_STRING_BYTES)?;
517	        self.add_already_done(operation, summary)
518	    }
519	
520	    /// Append a contextual hint.
521	    ///
522	    /// # Errors
523	    ///
524	    /// Rejects a hint over 1 MiB, any hint after the 10,000th, and a hint that would take the response past its
525	    /// 16 MiB total.
526	    #[napi(catch_unwind)]
527	    pub fn hint(&mut self, hint: String) -> napi::Result<()> {
528	        if self.hint_count >= MAX_HINTS {
529	            return Err(napi::Error::from_reason(format!("cumulative hint count exceeds maximum of {MAX_HINTS}")));
530	        }
531	        input::check_bytes("hint", &hint, MAX_STRING_BYTES)?;
532	        let bytes = hint.len().saturating_add(cost::HINT_OVERHEAD);
533	        self.held.check_replace(0, bytes)?;
534	        let b = self.take()?;
535	        self.inner = Some(b.hint(hint));
536	        self.hint_count += 1;
537	        self.held.hints = self.held.hints.saturating_add(bytes);
538	        Ok(())
539	    }
540	
541	    /// Append a recovery hint naming a tool.
542	    ///
543	    /// # Errors
544	    ///
545	    /// Rejects a `tool` over 4 KiB, a `reason` over 1 MiB, any recovery hint after the 10,000th, and one that would
546	    /// take the response past its 16 MiB total.
547	    #[napi(catch_unwind)]
548	    pub fn recovery_hint(&mut self, tool: String, reason: Option<String>) -> napi::Result<()> {
549	        if self.recovery_count >= MAX_HINTS {
550	            return Err(napi::Error::from_reason(format!(
551	                "cumulative recovery hint count exceeds maximum of {MAX_HINTS}"
552	            )));
553	        }
554	        input::check_bytes("tool", &tool, MAX_NAME_BYTES)?;
555	        if let Some(reason) = &reason {
556	            input::check_bytes("reason", reason, MAX_STRING_BYTES)?;
557	        }
558	        let bytes = sum([tool.len(), reason.as_ref().map_or(0, String::len), cost::RECOVERY_OVERHEAD]);
559	        self.held.check_replace(0, bytes)?;
560	        let b = self.take()?;
561	        let mut hint = crate::recovery::RecoveryHint::new(tool);
562	        if let Some(reason) = reason {
563	            hint = hint.reason(reason);
564	        }
565	        self.inner = Some(b.recovery_hint(hint));
566	        self.recovery_count += 1;
567	        self.held.recovery = self.held.recovery.saturating_add(bytes);
568	        Ok(())
569	    }
570	
571	    /// Set the caller's instruction for getting a cut TOON cell in full (e.g. `"full=true"`), delivered in `help[]`
572	    /// after the response's own hints when a cell was cut. Not called: the `truncated` block still reports each cut.
573	    /// Tool-author text, never data.
574	    ///
575	    /// # Errors
576	    ///
577	    /// Rejects a hint over 4 KiB, or one that would take the response past its 16 MiB total. A hint over 256 chars is
578	    /// accepted here but renders as a `toon_validation_failed` error block, like any other options michi-core's TOON
579	    /// validation rejects.
580	    #[napi(catch_unwind)]
581	    pub fn truncation_hint(&mut self, hint: String) -> napi::Result<()> {
582	        input::check_bytes("truncationHint", &hint, MAX_NAME_BYTES)?;
583	        let bytes = hint.len();
584	        self.held.check_replace(self.held.truncation_hint, bytes)?;
585	        let b = self.take()?;
586	        self.inner = Some(b.truncation_hint(hint));
587	        self.held.truncation_hint = bytes;
588	        Ok(())
589	    }
590	
591	    /// Mark this response as an error state.
592	    ///
593	    /// # Errors
594	    ///
595	    /// Returns an error if the builder was already consumed (an internal invariant; should not happen in normal use).
596	    #[napi(catch_unwind)]
597	    pub fn as_error(&mut self) -> napi::Result<()> {
598	        let b = self.take()?;
599	        self.inner = Some(b.as_error());
600	        Ok(())
601	    }
602	
603	    /// Attach a human-facing companion block (`audience: user`) for MCP callers. A second call replaces the first.
604	    ///
605	    /// # Errors
606	    ///
607	    /// Rejects text over 1 MiB, or text that would take the response past its 16 MiB total. The builder is unchanged
608	    /// on error.
609	    #[napi(catch_unwind)]
610	    pub fn human_content(&mut self, text: String) -> napi::Result<()> {
611	        input::check_bytes("humanContent", &text, MAX_STRING_BYTES)?;
612	        let bytes = text.len();
613	        self.held.check_replace(self.held.human_content, bytes)?;
614	        let b = self.take()?;
615	        self.inner = Some(b.human_content(text));
616	        self.held.human_content = bytes;
617	        Ok(())
618	    }
619	
620	    /// Render the response as text: the error block, its sections in call order, then `help[]` and `recovery[]`. The
621	    /// one text render; see [`crate::response::AgentResponse::render`].
622	    ///
623	    /// # Errors
624	    ///
625	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
626	    #[napi(catch_unwind)]
627	    pub fn render_text(&self) -> napi::Result<String> {
628	        Ok(self.built()?.render(crate::response::OutputFormat::Text))
629	    }
630	
631	    /// Render as a compact JSON string: `{"body":...,"error":{...},"sections":[...],"hints":[...],"recovery":[...],
632	    /// "isError":bool}`, with `error` and `sections` only when set.
633	    ///
634	    /// # Errors
635	    ///
636	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
637	    #[napi(catch_unwind)]
638	    pub fn render_json(&self) -> napi::Result<String> {
639	        Ok(self.built()?.render(crate::response::OutputFormat::Json))
640	    }
641	
642	    /// Render just the `help[N]:` block — the three-surface seam for MCP
643	    /// frameworks assembling their own display body separately.
644	    ///
645	    /// # Errors
646	    ///
647	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
648	    #[napi(catch_unwind)]
649	    pub fn render_hints_only(&self) -> napi::Result<String> {
650	        Ok(self.built()?.render_hints_only())
651	    }
652	
653	    /// Render for the given audience — `"assistant"` or `"user"`. `"user"`
654	    /// returns the `humanContent()` block if one was set, falling back to
655	    /// the same agent-oriented rendering `"assistant"` would produce
656	    /// otherwise — never an empty string. See [`Self::has_human_content`]
657	    /// to check for the fallback case ahead of time.
658	    ///
659	    /// # Errors
660	    ///
661	    /// Returns an error if `audience` is anything other than `"assistant"`
662	    /// or `"user"`, or if an internal invariant is violated (should not
663	    /// happen in normal use).
664	    #[napi(catch_unwind)]
665	    #[allow(clippy::needless_pass_by_value)] // napi-derive requires owned String for JS string params
666	    pub fn render_for(&self, audience: String) -> napi::Result<String> {
667	        let audience = match audience.as_str() {
668	            "assistant" => crate::audience::Audience::Assistant,
669	            "user" => crate::audience::Audience::User,
670	            other => {
671	                return Err(napi::Error::from_reason(format!(
672	                    "unknown audience {other:?}: expected \"assistant\" or \"user\""
673	                )))
674	            }
675	        };
676	        Ok(self.built()?.render_for(audience))
677	    }
678	
679	    /// Whether `.humanContent()` was set on this builder.
680	    ///
681	    /// # Errors
682	    ///
683	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
684	    #[napi(catch_unwind)]
685	    pub fn has_human_content(&self) -> napi::Result<bool> {
686	        Ok(self.built()?.has_human_content())
687	    }
688	
689	    /// Build the MCP `CallToolResult` for this response. Returns a real
690	    /// object, not a JSON string — `structuredContent` is a parsed
691	    /// `serde_json::Value`, so TypeScript callers don't need to
692	    /// `JSON.parse()` it themselves.
693	    ///
694	    /// # Errors
695	    ///
696	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
697	    #[napi(catch_unwind)]
698	    pub fn to_call_tool_result(&self) -> napi::Result<JsCallToolResult> {
699	        let result = self.built()?.to_call_tool_result();
700	        let structured_content =
701	            serde_json::from_str(result.structured_content.as_ref().map_or("null", |j| j.as_str()))
702	                .map_err(|e| napi::Error::from_reason(format!("structured_content was not valid JSON: {e}")))?;
703	        Ok(JsCallToolResult {
704	            content: result
705	                .content
706	                .into_iter()
707	                .map(|c| JsContentBlock {
708	                    content_type: "text".to_string(),
709	                    text: c.text,
710	                    annotations: JsAnnotations {
711	                        audience: c
712	                            .audience
713	                            .into_iter()
714	                            .map(|a| match a {
715	                                crate::audience::Audience::Assistant => "assistant".to_string(),
716	                                crate::audience::Audience::User => "user".to_string(),
717	                            })
718	                            .collect(),
719	                    },
720	                })

