1030	    #[test]
1031	    fn agent_response_empty_sections_are_charged_for_their_name_and_overhead() {
1032	        // Each empty `items` / `kvItems` call still stores a section with a copy of the type name, so it costs bytes.
1033	        for kv in [false, true] {
1034	            let mut r = new_response("t".repeat(MAX_NAME_BYTES));
1035	            let mut accepted = 0usize;
1036	            while accepted <= 1_000_000 {
1037	                let added = if kv { r.add_kv_items(vec![], None) } else { r.add_items(vec![], vec![], None) };
1038	                if added.is_err() {
1039	                    break;
1040	                }
1041	                accepted += 1;
1042	            }
1043	            // 16 MiB / (4 KiB name + overhead) is about 4k sections; uncharged, the loop would run past a million.
1044	            assert!(accepted < 5_000, "{accepted} empty sections accepted (kv: {kv})");
1045	            assert!(accepted > 2_500, "{accepted} empty sections accepted (kv: {kv}): overhead too large");
1046	        }
