1049	    #[test]
1050	    fn agent_response_rows_and_non_string_cells_are_charged_for_the_storage_they_keep() {
1051	        // `Array(100000).fill([])`: no strings at all, yet every call keeps 100,000 row vectors. Charging string
1052	        // bytes only let a loop of these retain gigabytes, since each call now appends a section instead of
1053	        // replacing the rows.
1054	        let empty_rows = || vec![Vec::<JsToonValue>::new(); MAX_ROWS];
1055	        let mut r = new_response("t".to_string());
1056	        let mut accepted = 0usize;
1057	        while accepted < 1_000 {
1058	            if r.add_items(empty_rows(), vec![], None).is_err() {
1059	                break;
1060	            }
1061	            accepted += 1;
1062	        }
1063	        // 16 MiB / (100,000 rows * 24 bytes) is about 7 calls. Uncharged, the loop would run to its cap.
1064	        assert!(accepted < 100, "{accepted} calls of {MAX_ROWS} empty rows accepted");
1065	        assert!(accepted > 3, "{accepted} calls accepted: row charge is too large");
1066	
1067	        // A cell that is not a string also keeps a `Value`, so a number-only table is not free either.
1068	        let null_cell = || JsToonValue { r#type: "null".to_string(), ..JsToonValue::default() };
1069	        let mut r = new_response("t".to_string());
1070	        assert!(
1071	            r.add_items(vec![vec![null_cell()]], vec!["a".to_string()], None).is_ok(),
1072	            "a null cell is a valid cell"
1073	        );
1074	        let mut accepted = 0usize;
1075	        while accepted < 100_000 {
1076	            if r.add_items(vec![vec![null_cell(); MAX_FIELDS]; 300], vec![], None).is_err() {
1077	                break;
1078	            }
1079	            accepted += 1;
1080	        }
1081	        // 300,000 cells * 24 bytes = 7.2 MB a call, so two fit in 16 MiB; uncharged, the loop would run to its cap.
1082	        assert!((1..10).contains(&accepted), "{accepted} calls of 300,000 non-string cells accepted");
1083	    }
