199	            operation: one(),
200	            reason: one(),
201	            recovery: Some(super::super::hints::JsRecoveryHint { tool: one(), reason: None }),
202	        })
203	        .collect();
204	    let skipped = (0..n).map(|i| JsSkippedOp { index: count(2 * n + i), operation: one(), reason: None }).collect();
205	    r.add_partial_success("p".into(), completed, failed, skipped).expect("fits");
206	    let steps =
207	        (0..n).map(|_| JsPipelineStep { id: one(), name: one(), status: "completed".into(), reason: None }).collect();
208	    r.add_pipeline("s".into(), steps).expect("fits");
209	    r
210	}
211	
212	/// How one case fills a response.
213	type Build<'a> = Box<dyn Fn(&mut JsAgentResponse) + 'a>;
214	
215	/// One kind of tiny item at its per-call cap, alone, so that nothing else's charge can hide an item that is charged
216	/// too little.
217	fn one_kind(unit: char) -> Vec<(String, JsAgentResponse)> {
218	    let one = || one(unit);
219	    let n = u32::try_from(MAX_STEPS).expect("fits");
220	    let recovery = || Some(super::super::hints::JsRecoveryHint { tool: one(), reason: None });
221	    let builds: Vec<(&str, Build<'_>)> = vec![
222	        ("hints", Box::new(|r| (0..MAX_HINTS).for_each(|_| r.hint(one()).expect("fits")))),
223	        ("empty hints", Box::new(|r| (0..MAX_HINTS).for_each(|_| r.hint(String::new()).expect("fits")))),
224	        ("recovery hints", Box::new(|r| (0..MAX_HINTS).for_each(|_| r.recovery_hint(one(), None).expect("fits")))),
225	        (
226	            "recovery hints with reasons",
227	            Box::new(|r| (0..MAX_HINTS).for_each(|_| r.recovery_hint(one(), Some(one())).expect("fits"))),
228	        ),
229	        (
230	            "causes",
231	            Box::new(|r| {
232	                r.set_error("not_found", one(), (0..MAX_HINTS).map(|_| one()).collect(), None).expect("fits");
233	            }),
234	        ),
235	        (
236	            "kv items",
237	            Box::new(|r| {
238	                let items = (0..MAX_FIELDS).map(|i| JsKvItem { key: format!("{unit}{i}"), value: tag("null") });
239	                r.add_kv_items(items.collect(), None).expect("fits");
240	            }),
241	        ),
242	        (
243	            "completed operations",
244	            Box::new(|r| {
245	                let ops = (0..n).map(|i| JsCompletedOp { index: count(i), operation: one() });
246	                r.add_partial_success("p".into(), ops.collect(), Vec::new(), Vec::new()).expect("fits");
247	            }),
248	        ),
249	        (
250	            "failed operations",
251	            Box::new(|r| {
252	                let ops =
253	                    (0..n).map(|i| JsFailedOp { index: count(i), operation: one(), reason: one(), recovery: None });
254	                r.add_partial_success("p".into(), Vec::new(), ops.collect(), Vec::new()).expect("fits");
255	            }),
256	        ),
257	        (
258	            "failed operations with recovery",
259	            Box::new(|r| {
260	                let ops = (0..n).map(|i| JsFailedOp {
261	                    index: count(i),
262	                    operation: one(),
263	                    reason: one(),
264	                    recovery: recovery(),
265	                });
266	                r.add_partial_success("p".into(), Vec::new(), ops.collect(), Vec::new()).expect("fits");
267	            }),
268	        ),
269	        (
270	            "skipped operations",
271	            Box::new(|r| {
272	                let ops = (0..n).map(|i| JsSkippedOp { index: count(i), operation: one(), reason: Some(one()) });
273	                r.add_partial_success("p".into(), Vec::new(), Vec::new(), ops.collect()).expect("fits");
274	            }),
275	        ),
276	        (
277	            "pipeline steps",
278	            Box::new(|r| {
279	                let step = || JsPipelineStep { id: one(), name: one(), status: "pending".into(), reason: None };
280	                r.add_pipeline("s".into(), (0..n).map(|_| step()).collect()).expect("fits");
281	            }),
282	        ),
283	        (
284	            "status items",
285	            Box::new(|r| {
286	                let item = |i: usize| JsStatusItem { key: format!("{unit}{i}"), value: tag("null"), health: None };
287	                r.add_status(one(), one(), (0..MAX_FIELDS).map(item).collect()).expect("fits");
288	            }),
289	        ),
290	        (
291	            "rows of one cell",
292	            Box::new(|r| {
293	                r.add_items(vec![vec![str_cell(one())]; MAX_ROWS], vec!["a".into()], None).expect("fits");
294	            }),
295	        ),
296	    ];
297	    builds
298	        .into_iter()
299	        .map(|(label, build)| {
300	            let mut r = JsAgentResponse::new("t".into()).expect("a valid type name");
301	            build(&mut r);
302	            (label.to_string(), r)
303	        })
304	        .collect()
305	}
306	
307	/// Tables with no rows: each writes `name: []` and a `totalCount` row that names it again.
308	fn empty_tables(unit: char, name_bytes: usize) -> JsAgentResponse {
309	    let mut r = cut_table(unit, name_bytes, 4);
310	    r.add_partial_success(name(unit, name_bytes, 'p'), Vec::new(), Vec::new(), Vec::new()).expect("fits");
311	    r.add_pipeline(name(unit, name_bytes, 's'), Vec::new()).expect("fits");
312	    r
313	}
314	
315	/// KV items with one-byte keys and the widest numbers, in a status report and in KV sections.
316	fn wide_numbers() -> JsAgentResponse {
317	    let mut r = JsAgentResponse::new("t".into()).expect("a valid type name");
318	    let items = |prefix: &str| {
319	        (0..MAX_FIELDS / 2)
320	            .map(|i| JsKvItem {
321	                key: format!("{prefix}{i}"),
322	                value: match i % 3 {
323	                    0 => float_cell(f64::MAX, Some(20.0)),
324	                    1 => float_cell(1e-250, None),
325	                    _ => float_cell(-f64::MAX, Some(0.0)),
326	                },
327	            })
328	            .collect::<Vec<_>>()
329	    };
330	    r.add_kv_items(items("k"), Some(count(9))).expect("fits");
331	    let status = items("s").into_iter().map(|i| JsStatusItem { key: i.key, value: i.value, health: None }).collect();
332	    r.add_status("tool".into(), "desc".into(), status).expect("fits");
333	    r
334	}
335	
336	/// Rows with no cells, and rows of numbers and nulls.
337	fn bare_cells() -> Vec<JsAgentResponse> {
338	    let mut empty_rows = JsAgentResponse::new("t".into()).expect("a valid type name");
339	    empty_rows.add_items(vec![Vec::new(); MAX_ROWS], Vec::new(), None).expect("fits");
340	    let mut numbers = JsAgentResponse::new("t".into()).expect("a valid type name");
341	    let row = vec![
342	        int_cell(-9_007_199_254_740_991.0),
343	        float_cell(-f64::MAX, None),
344	        float_cell(-5e-324, None),
345	        tag("null"),
346	        JsToonValue { bool_val: Some(false), ..tag("bool") },
347	    ];
348	    numbers.add_items(vec![row; MAX_ROWS], ["a", "b", "c", "d", "e"].map(String::from).to_vec(), None).expect("fits");
349	    vec![empty_rows, numbers, JsAgentResponse::new(String::new()).expect("an empty type name is valid")]
350	}
351	
352	/// Every case for `unit`, with the label that names it in a failure.
353	fn matrix(unit: char) -> Vec<(String, JsAgentResponse)> {
354	    let cases = vec![
355	        ("cut table, 4 KiB names".to_string(), cut_table(unit, MAX_NAME_BYTES, 60)),
356	        ("cut table, 64 B names".to_string(), cut_table(unit, 64, 200)),
357	        ("cut table, long fields".to_string(), named_cut_table(unit, 8, MAX_NAME_BYTES, 60)),
358	        ("cut table, long type name".to_string(), named_cut_table(unit, MAX_NAME_BYTES, 8, 60)),
359	        ("long type name beside a cut section".to_string(), long_name_beside_a_cut_section(unit)),
360	        ("outcome name in header and total".to_string(), name_in_header_and_total(unit).remove(0)),
361	        ("type name in header and total".to_string(), name_in_header_and_total(unit).remove(1)),
362	        ("every section cut, 4 KiB names".to_string(), shared_tables(unit, MAX_NAME_BYTES, 8)),
363	        ("kv sections with totals".to_string(), kv_sections(unit, MAX_NAME_BYTES)),
364	        ("error, hints, recovery".to_string(), with_error(unit)),
365	        ("empty tables, 4 KiB names".to_string(), empty_tables(unit, MAX_NAME_BYTES)),
366	        ("tiny strings".to_string(), tiny(unit)),
367	        ("tiny operations".to_string(), tiny_outcomes(unit)),
368	    ];
369	    cases
370	}
371	
372	/// The cases that do not depend on a character.
373	fn fixed_cases() -> Vec<(String, JsAgentResponse)> {
374	    let mut cases = vec![("wide numbers".to_string(), wide_numbers())];
375	    cases.extend(bare_cells().into_iter().enumerate().map(|(i, r)| (format!("bare cells {i}"), r)));
376	    cases
377	}
378	
379	/// The worst `output / held` ratio (as a percentage) over `cases`, as `(percent, label)`. Panics naming every case
380	/// whose output is over [`input::MAX_OUTPUT_FACTOR`] times the bytes held plus [`input::OUTPUT_ENVELOPE`].
381	fn worst_ratio(cases: impl Iterator<Item = (String, JsAgentResponse)>) -> (usize, String) {
382	    let mut worst: (usize, String) = (0, String::new());
383	    let mut broken: Vec<String> = Vec::new();
384	    for (label, r) in cases {
385	        let held = r.held.total();
386	        for (surface, out) in ["text", "json", "toCallToolResult"].into_iter().zip(output_sizes(&r)) {
387	            let limit = input::MAX_OUTPUT_FACTOR * held + input::OUTPUT_ENVELOPE;
388	            let ratio = out * 100 / held.max(1);
389	            if out > limit {
390	                broken.push(format!("{label}, {surface}: {out} bytes for {held} held ({}x)", ratio / 100));
391	            }
392	            if ratio > worst.0 {
393	                worst = (ratio, format!("{label}, {surface}"));
394	            }
395	        }
396	    }
397	    broken.dedup();
398	    assert!(
399	        broken.is_empty(),
400	        "output over {}x the bytes held + {}:\n{}",
401	        input::MAX_OUTPUT_FACTOR,
402	        input::OUTPUT_ENVELOPE,
403	        broken.join("\n")
404	    );
405	    worst
406	}
407	
408	fn unit_cases(unit: char) -> impl Iterator<Item = (String, JsAgentResponse)> {
409	    matrix(unit).into_iter().chain(one_kind(unit)).map(move |(l, r)| (format!("{l}, unit {unit:?}"), r))
410	}
411	
412	/// One test per character (every control character and escape trigger, plain text, and multi-byte characters, which
413	/// cost fewer output bytes per held byte, never more), so the matrix runs in parallel (about 17 s in one test in a debug build, under 3 s as
414	/// the slowest of these) and a failure names its character.
415	macro_rules! bound_test {
416	    ($($name:ident: $unit:expr),* $(,)?) => {$(
417	        #[test]
418	        fn $name() {
419	            worst_ratio(unit_cases($unit));
420	        }
421	    )*};
422	}
423	
424	bound_test! {
425	    every_render_of_control_unit_separator_is_within_the_factor: '\u{1f}',
426	    every_render_of_a_quote_is_within_the_factor: '"',
427	    every_render_of_a_backslash_is_within_the_factor: '\\',
428	    every_render_of_a_newline_is_within_the_factor: '\n',
429	    every_render_of_a_comma_is_within_the_factor: ',',
430	    every_render_of_plain_text_is_within_the_factor: 'a',
431	    every_render_of_two_byte_text_is_within_the_factor: '\u{e9}',
432	    every_render_of_four_byte_text_is_within_the_factor: '\u{1f600}',
433	}
434	
435	#[test]
436	fn the_fixed_cases_are_within_the_factor() {
437	    worst_ratio(fixed_cases().into_iter());
438	}
439	
440	/// `U+0001` is the worst escape (six JSON bytes for one held), and with it the factor is reached, not just an upper
441	/// bound nobody comes near: a loosened `MAX_OUTPUT_FACTOR` fails here.
442	#[test]
443	fn the_worst_character_reaches_the_documented_factor() {
444	    let worst = worst_ratio(unit_cases('\u{1}'));
445	    assert!(
446	        worst.0 > 1500,
447	        "worst ratio {}/100 ({}): the documented factor of {} is loose",
448	        worst.0,
449	        worst.1,
450	        input::MAX_OUTPUT_FACTOR
451	    );
452	}
453	
454	/// The amplification the review found: a 4 KiB control-character field name that a `truncated` row writes for every
455	/// cut cell, charged once. 1,000 rows of one 201-char cell held about 261 KB and rendered to 95x in text.
456	#[test]
457	fn a_long_field_name_is_charged_for_every_cell_it_can_be_repeated_in() {
458	    let mut r = JsAgentResponse::new("t".into()).expect("a valid type name");
459	    let field = text('\u{1}', MAX_NAME_BYTES);
460	    r.add_items(cut_rows('a', 1000, 1), vec![field], None).expect("fits");
461	    let [text_out, json_out, _] = output_sizes(&r);
462	    let held = r.held.total();
463	    assert!(held > 1000 * MAX_NAME_BYTES, "{held} bytes held: each cut cell can write the field name again");
464	    assert!(text_out <= input::MAX_OUTPUT_FACTOR * held, "{text_out} text bytes for {held} held");
465	    assert!(json_out <= input::MAX_OUTPUT_FACTOR * held, "{json_out} JSON bytes for {held} held");
466	}
467	
468	/// The same, for a section name: a multi-section `truncated` row writes it for every cut cell.
469	#[test]
470	fn a_long_section_name_is_charged_for_every_cell_it_can_be_repeated_in() {
471	    let mut r = cut_table('a', 16, 1);
472	    r.add_pipeline(
473	        text('\u{1}', MAX_NAME_BYTES),
474	        (0..500)
475	            .map(|_| JsPipelineStep { id: text('a', 201), name: "n".into(), status: "completed".into(), reason: None })
476	            .collect(),
477	    )
478	    .expect("fits");
479	    let held = r.held.total();
480	    assert!(held > 500 * MAX_NAME_BYTES, "{held} bytes held: each cut cell can write the section name again");
481	    assert!(output_sizes(&r)[0] <= input::MAX_OUTPUT_FACTOR * held);
482	}
483	
484	/// The cap on what a response holds is what stops a hostile table: 60,000 rows of the review's reproduction used to
485	/// fit under the cap and then fail to render.
486	/// An error report as large as one call may carry (10,000 causes, under the 16 MiB string cap) fits a fresh builder:
487	/// the report must not be lost while handling the failure it describes.
488	#[test]
489	fn a_full_error_report_fits_a_fresh_builder() {
490	    let mut r = JsAgentResponse::new("t".into()).expect("a valid type name");
491	    let causes: Vec<String> = (0..MAX_HINTS).map(|_| text('a', 1_660)).collect();
492	    r.set_error("external_failure", text('a', 100), causes, None).expect("one call's worth of causes fits");
493	    let [text_len, json_len, mcp_len] = output_sizes(&r);
494	    let bound = input::MAX_OUTPUT_FACTOR * input::MAX_INPUT_BYTES + input::OUTPUT_ENVELOPE;
495	    assert!(text_len.max(json_len).max(mcp_len) <= bound, "rendered past the output bound");
496	}
497	
498	#[test]
499	fn the_reviews_reproduction_is_rejected_before_rendering() {
500	    let mut r = JsAgentResponse::new("t".into()).expect("a valid type name");
501	    let field = text('\u{1}', MAX_NAME_BYTES);
502	    let err = r.add_items(cut_rows('a', 60_000, 1), vec![field], None).expect_err("over the cap");
503	    assert!(err.reason.starts_with("cumulative byte total"), "{}", err.reason);
504	}
505

