//! Bounded, incremental conversion of caller-supplied JS values.
//!
//! napi-derive converts a `Vec<Vec<JsToonValue>>` or `String` parameter in full before the export's body runs, so a
//! size check in the body comes too late: a rejected 100,001 × 100 `rows` array cost 3.4 s and 2.6 GiB, and 10k × 10
//! cells sharing one 100 KB JS string were copied out once per cell (~10 GB). The exports therefore take untyped napi
//! values and convert them here: array lengths are checked before any element is read, and every string's UTF-8
//! length is read and charged to a per-call [`Budget`] before the string is copied.

use napi::bindgen_prelude::{FromNapiValue, JsObjectValue as _, Object, Unknown};
use napi::{JsString, JsValue as _, ValueType};

use super::hints::JsRecoveryHint;
use super::num::JsCount;
use super::outcome::{JsCompletedOp, JsFailedOp, JsPipelineStep, JsSkippedOp};
use super::toon::JsStatusItem;
use super::value::{JsKvItem, JsToonValue};

/// Most rows one call's `rows` may hold (`renderToon`'s `opts.rows`, `AgentResponse.items`'s `rows`).
pub(crate) const MAX_ROWS: usize = 100_000;
/// Most entries for anything shaped like "one entry per field": `fields`, each row's value count, and the `items` of
/// `renderKv`, `AgentResponse.kvItems` and `AgentResponse.status` (one KV entry is one field).
pub(crate) const MAX_FIELDS: usize = 1_000;
/// Most hints per call (`hints`, `causes`, recovery hints), and the cumulative count one `AgentResponse` takes
/// through `hint` and `recoveryHint`.
pub(crate) const MAX_HINTS: usize = 10_000;
/// Most entries per list for `AgentResponse.partialSuccess`'s `completed`, `failed` and `skipped` and
/// `AgentResponse.pipeline`'s `steps`.
pub(crate) const MAX_STEPS: usize = 10_000;
/// Most cells (row values) one call may pass.
pub(crate) const MAX_CELLS: usize = 1_000_000;
/// Most UTF-8 bytes of string data one call may pass, summed over every string argument and nested string, and most
/// one `AgentResponse` may hold across all its calls.
///
/// This bounds the OUTPUT as well as the input: a render is at most [`MAX_OUTPUT_FACTOR`] times the bytes held, plus
/// [`OUTPUT_ENVELOPE`], on every surface. Rendering writes a string in more than one place, and a control character
/// is the worst case: `\u0001` is six bytes in the text, seven in the JSON `body` (the text, escaped again) and six in
/// the raw `sections`, `error` and `hints` copies, so one held byte is at most 6 + 7 + 6 = 19 output bytes across the
/// text and the JSON that `toCallToolResult` returns together. A name is written in more places than that (a
/// `truncated` row repeats the field name and the section name for every cut cell, and a `totalCount` row repeats the
/// section name), so the bytes held count a name once for every place it can be written (see [`super::cost`]). At the
/// old 64 MiB that was 1.2 GiB per call on Node's event loop, and a response over V8's string limit (about 512 MiB)
/// failed only after rendering it. At 16 MiB it is at most 304 MiB, under that limit, so a response either renders or
/// is rejected here, before anything is rendered.
///
/// The one-shot renders write text only: at most 6 bytes per byte charged, and what the counts allow beyond that (see
/// [`STANDALONE_OUTPUT_MAX`]).
pub(crate) const MAX_INPUT_BYTES: usize = 16 * 1024 * 1024;
/// Largest ratio of any render's output to the bytes held (see [`MAX_INPUT_BYTES`]); tests measure it.
pub(crate) const MAX_OUTPUT_FACTOR: usize = 19;
/// Bytes of output that no held byte pays for: the fixed parts of the envelope (the `help[]`, `recovery[]` and
/// `totalCount` headers, the JSON keys).
pub(crate) const OUTPUT_ENVELOPE: usize = 4096;
/// V8's longest string, in characters, on 64-bit builds (`2^29 - 24`). A string longer than this cannot be handed to
/// JavaScript, so every output must stay under it.
pub(crate) const V8_MAX_STRING_LEN: usize = (1 << 29) - 24;
const _: () = assert!(MAX_INPUT_BYTES * MAX_OUTPUT_FACTOR + OUTPUT_ENVELOPE < V8_MAX_STRING_LEN);
/// The most text one of the one-shot renders (`renderToon`, `renderKv`, `renderHints`, `renderRecovery`,
/// `renderGithubAnnotation`, ...) can write: 6 bytes for each string byte charged, 26 for each cell (a float is at
/// most 24 chars, and the comma), 4 for each row, and 400 for each other entry (a KV item holds a float written to
/// 330 places; a hint is a short row).
pub(crate) const STANDALONE_OUTPUT_MAX: usize =
    6 * MAX_INPUT_BYTES + 26 * MAX_CELLS + 4 * MAX_ROWS + 400 * (MAX_FIELDS + MAX_HINTS);
const _: () = assert!(STANDALONE_OUTPUT_MAX < V8_MAX_STRING_LEN);
/// Longest single cell value, hint, reason, description or message, in UTF-8 bytes.
pub(crate) const MAX_STRING_BYTES: usize = 1024 * 1024;
/// Longest type name, field name, key, tool name, error code, truncation hint or other identifier, in UTF-8 bytes.
pub(crate) const MAX_NAME_BYTES: usize = 4 * 1024;

/// `"{what} length {len} exceeds maximum of {max}"` when `len > max`.
pub(crate) fn check_len(what: &str, len: usize, max: usize) -> napi::Result<()> {
    if len > max {
        return Err(napi::Error::from_reason(format!("{what} length {len} exceeds maximum of {max}")));
    }
    Ok(())
}

/// `"{what} byte length {len} exceeds maximum of {max}"` for a string argument napi has already copied. Used by the
/// single-string builder methods: their one argument is copied once, so the cap bounds what is kept, not the copy.
pub(crate) fn check_bytes(what: &str, s: &str, max: usize) -> napi::Result<()> {
    if s.len() > max {
        return Err(napi::Error::from_reason(format!("{what} byte length {} exceeds maximum of {max}", s.len())));
    }
    Ok(())
}

/// A JS array whose length has been read but none of whose elements have.
pub(crate) struct List<'env> {
    obj: Object<'env>,
    len: u32,
}

impl<'env> List<'env> {
    /// `value` as an array, or an error saying `what` must be one.
    pub(crate) fn new(value: Unknown<'env>, what: &str) -> napi::Result<Self> {
        if !value.is_array()? {
            return Err(napi::Error::from_reason(format!("{what} must be an array")));
        }
        // Coercing an object to an object returns it unchanged.
        let obj = value.coerce_to_object()?;
        let len = obj.get_array_length_unchecked()?;
        Ok(Self { obj, len })
    }

    /// `value` as an array, or `None` when it is absent, `undefined` or `null`.
    pub(crate) fn optional(value: Option<Unknown<'env>>, what: &str) -> napi::Result<Option<Self>> {
        match value {
            Some(v) if !is_nullish(v)? => Self::new(v, what).map(Some),
            _ => Ok(None),
        }
    }

    /// The element count.
    pub(crate) fn len(&self) -> usize {
        usize::try_from(self.len).unwrap_or(usize::MAX)
    }

    fn get(&self, index: u32) -> napi::Result<Unknown<'env>> {
        self.obj.get_element::<Unknown<'env>>(index)
    }
}

pub(crate) fn is_nullish(value: Unknown<'_>) -> napi::Result<bool> {
    Ok(matches!(value.get_type()?, ValueType::Undefined | ValueType::Null))
}

fn missing(name: &str) -> napi::Error {
    napi::Error::from_reason(format!("Missing field `{name}`"))
}

/// `value` as an object, or an error saying `what` must be one.
pub(crate) fn object<'env>(value: Unknown<'env>, what: &str) -> napi::Result<Object<'env>> {
    if value.get_type()? != ValueType::Object {
        return Err(napi::Error::from_reason(format!("{what} must be an object")));
    }
    value.coerce_to_object()
}

/// Property `name`, or `None` when it is absent or `undefined`. As with napi-derive's generated object conversion,
/// `null` is a value (and so rejected wherever a string, number or object is expected), not an absent field.
fn prop<'env>(obj: &Object<'env>, name: &str) -> napi::Result<Option<Unknown<'env>>> {
    obj.get::<Unknown<'env>>(name)
}

/// A scalar property converted by its type's own `FromNapiValue` (the numeric newtypes reject out-of-domain numbers
/// with their usual messages); `None` when absent or `undefined`.
pub(crate) fn typed_prop<T: FromNapiValue>(obj: &Object<'_>, name: &str) -> napi::Result<Option<T>> {
    obj.get::<T>(name)
}

/// A required array property.
pub(crate) fn list_prop<'env>(obj: &Object<'env>, name: &str) -> napi::Result<List<'env>> {
    List::new(prop(obj, name)?.ok_or_else(|| missing(name))?, name)
}

/// Per-call accounting of cells and string bytes.
pub(crate) struct Budget {
    cells: usize,
    bytes: usize,
}

impl Budget {
    /// A fresh budget for one export call.
    pub(crate) fn new() -> Self {
        Self { cells: 0, bytes: 0 }
    }

    /// Charge `n` cells, failing once the call's total passes [`MAX_CELLS`].
    fn charge_cells(&mut self, n: usize) -> napi::Result<()> {
        self.cells = self.cells.saturating_add(n);
        if self.cells > MAX_CELLS {
            return Err(napi::Error::from_reason(format!("cell count {} exceeds maximum of {MAX_CELLS}", self.cells)));
        }
        Ok(())
    }

    /// Charge `n` bytes, failing once the call's total passes [`MAX_INPUT_BYTES`]. Strings are charged by their length
    /// as they are read; a table's names are charged here for each cell they can be written beside (see
    /// [`super::cost`]).
    pub(crate) fn charge_bytes(&mut self, n: usize) -> napi::Result<()> {
        self.bytes = self.bytes.saturating_add(n);
        if self.bytes > MAX_INPUT_BYTES {
            return Err(napi::Error::from_reason(format!(
                "input byte total {} exceeds maximum of {MAX_INPUT_BYTES}",
                self.bytes
            )));
        }
        Ok(())
    }

    /// Copy the JS string `value` out after checking it is a string of at most `max` UTF-8 bytes and charging its
    /// length to the call's byte budget. The UTF-16 length rejects most oversize strings without scanning them,
    /// since a string never has fewer UTF-8 bytes than UTF-16 units.
    pub(crate) fn string(&mut self, value: Unknown<'_>, what: &str, max: usize) -> napi::Result<String> {
        if value.get_type()? != ValueType::String {
            return Err(napi::Error::from_reason(format!("{what} must be a string")));
        }
        let s: JsString<'_> = value.coerce_to_string()?;
        let units = s.utf16_len()?;
        if units > max {
            return Err(napi::Error::from_reason(format!(
                "{what} byte length (at least {units}) exceeds maximum of {max}"
            )));
        }
        let len = s.utf8_len()?;
        if len > max {
            return Err(napi::Error::from_reason(format!("{what} byte length {len} exceeds maximum of {max}")));
        }
        self.charge_bytes(len)?;
        s.into_utf8()?.into_owned()
    }

    /// An optional string property: `None` when absent or `undefined`.
    pub(crate) fn opt_string_prop(
        &mut self,
        obj: &Object<'_>,
        name: &str,
        what: &str,
        max: usize,
    ) -> napi::Result<Option<String>> {
        match prop(obj, name)? {
            Some(value) => self.string(value, what, max).map(Some),
            None => Ok(None),
        }
    }

    /// An optional string property where `null` also means absent, for fields whose TypeScript type admits `null`.
    fn nullable_string_prop(&mut self, obj: &Object<'_>, name: &str, max: usize) -> napi::Result<Option<String>> {
        match prop(obj, name)? {
            Some(value) if !is_nullish(value)? => self.string(value, name, max).map(Some),
            _ => Ok(None),
        }
    }

    /// A required string property.
    pub(crate) fn string_prop(&mut self, obj: &Object<'_>, name: &str, what: &str, max: usize) -> napi::Result<String> {
        self.opt_string_prop(obj, name, what, max)?.ok_or_else(|| missing(name))
    }

    /// An array of strings: its length checked against `max_len` first, then each string against `max_item`.
    pub(crate) fn strings(
        &mut self,
        list: &List<'_>,
        what_len: &str,
        max_len: usize,
        what_item: &str,
        max_item: usize,
    ) -> napi::Result<Vec<String>> {
        check_len(what_len, list.len(), max_len)?;
        let mut out = Vec::with_capacity(list.len());
        for i in 0..list.len {
            out.push(self.string(list.get(i)?, what_item, max_item)?);
        }
        Ok(out)
    }

    /// One `JsToonValue` object. Only the payload field its `type` names (plus `decimalsVal` for floats) is read, so
    /// an unused payload costs nothing.
    fn toon_value(&mut self, value: Unknown<'_>) -> napi::Result<JsToonValue> {
        let obj = object(value, "ToonValue")?;
        let r#type = self.string_prop(&obj, "type", "ToonValue type", MAX_NAME_BYTES)?;
        let mut out = JsToonValue { r#type, ..JsToonValue::default() };
        match out.r#type.as_str() {
            "str" => out.str_val = self.opt_string_prop(&obj, "strVal", "strVal", MAX_STRING_BYTES)?,
            "int" => out.int_val = typed_prop(&obj, "intVal")?,
            "float" => {
                out.float_val = typed_prop(&obj, "floatVal")?;
                out.decimals_val = typed_prop(&obj, "decimalsVal")?;
            }
            "bool" => out.bool_val = typed_prop(&obj, "boolVal")?,
            _ => {}
        }
        Ok(out)
    }

    /// `rows`: the row count and every row's length are checked, and the cells charged, before any cell is read.
    pub(crate) fn rows(
        &mut self,
        rows: &List<'_>,
        max_rows: usize,
        max_row_len: usize,
        row_len_limit: &str,
    ) -> napi::Result<Vec<Vec<JsToonValue>>> {
        check_len("rows", rows.len(), max_rows)?;
        let mut lists = Vec::with_capacity(rows.len());
        for i in 0..rows.len {
            let row = List::new(rows.get(i)?, "each row")?;
            if row.len() > max_row_len {
                return Err(napi::Error::from_reason(format!(
                    "row length {} exceeds {row_len_limit} of {max_row_len}",
                    row.len()
                )));
            }
            self.charge_cells(row.len())?;
            lists.push(row);
        }
        let mut out = Vec::with_capacity(lists.len());
        for row in &lists {
            let mut cells = Vec::with_capacity(row.len());
            for j in 0..row.len {
                cells.push(self.toon_value(row.get(j)?)?);
            }
            out.push(cells);
        }
        Ok(out)
    }

    /// `JsKvItem[]`, at most `max` items.
    pub(crate) fn kv_items(&mut self, items: &List<'_>, max: usize) -> napi::Result<Vec<JsKvItem>> {
        check_len("items", items.len(), max)?;
        let mut out = Vec::with_capacity(items.len());
        for i in 0..items.len {
            let obj = object(items.get(i)?, "KvItem")?;
            let key = self.string_prop(&obj, "key", "key", MAX_NAME_BYTES)?;
            let value = self.toon_value(prop(&obj, "value")?.ok_or_else(|| missing("value"))?)?;
            out.push(JsKvItem { key, value });
        }
        Ok(out)
    }

    /// `JsStatusItem[]`, at most `max` items.
    pub(crate) fn status_items(&mut self, items: &List<'_>, max: usize) -> napi::Result<Vec<JsStatusItem>> {
        check_len("items", items.len(), max)?;
        let mut out = Vec::with_capacity(items.len());
        for i in 0..items.len {
            let obj = object(items.get(i)?, "StatusItem")?;
            let key = self.string_prop(&obj, "key", "key", MAX_NAME_BYTES)?;
            let value = self.toon_value(prop(&obj, "value")?.ok_or_else(|| missing("value"))?)?;
            let health = self.opt_string_prop(&obj, "health", "health", MAX_STRING_BYTES)?;
            out.push(JsStatusItem { key, value, health });
        }
        Ok(out)
    }

    /// One `JsRecoveryHint` object.
    fn recovery_hint(&mut self, value: Unknown<'_>) -> napi::Result<JsRecoveryHint> {
        let obj = object(value, "RecoveryHint")?;
        let tool = self.string_prop(&obj, "tool", "tool", MAX_NAME_BYTES)?;
        let reason = self.opt_string_prop(&obj, "reason", "reason", MAX_STRING_BYTES)?;
        Ok(JsRecoveryHint { tool, reason })
    }
//! The `ToonValue` cell shared by every export that takes a value, and its one conversion into michi-core values.

use napi_derive::napi;

use super::num::{JsDecimals, JsFloat, JsInt};

/// Value type for a TOON row cell (JavaScript-friendly).
///
/// Use the `type` field to discriminate: `"str"`, `"int"`, `"float"`, `"bool"`, `"null"`.
#[napi(object, js_name = "ToonValue")]
#[derive(Debug, Clone, Default)]
pub struct JsToonValue {
    /// Discriminant: `"str"`, `"int"`, `"float"`, `"bool"`, or `"null"`.
    #[napi(js_name = "type")]
    pub r#type: String,
    /// The value when `type` is `"str"`.
    #[napi(js_name = "strVal")]
    pub str_val: Option<String>,
    /// The value when `type` is `"int"`.
    #[napi(js_name = "intVal", ts_type = "number")]
    pub int_val: Option<JsInt>,
    /// The value when `type` is `"float"`.
    #[napi(js_name = "floatVal", ts_type = "number")]
    pub float_val: Option<JsFloat>,
    /// The value when `type` is `"bool"`.
    #[napi(js_name = "boolVal")]
    pub bool_val: Option<bool>,
    /// Decimal places when `type` is `"float"` (KV and status render only). Rejected if outside [0, 20]. Omitted, the
    /// value keeps every digit it needs, so `1e-7` renders `1e-7` and `5e-324` renders `5e-324`. Given, it rounds as
    /// asked: `1e-7` with `decimalsVal: 2` renders `0`.
    #[napi(js_name = "decimalsVal", ts_type = "number")]
    pub decimals_val: Option<JsDecimals>,
}

/// A key-value item for `AgentResponse.kvItems` and `renderKv` (JavaScript-friendly).
#[napi(object, js_name = "KvItem")]
#[derive(Debug, Clone)]
pub struct JsKvItem {
    /// The field name.
    pub key: String,
    /// The field value.
    pub value: JsToonValue,
}

/// A [`JsToonValue`] checked against its `type` tag: the payload that tag names is present, and no other is read.
/// Both document families (TOON tables and KV lines) build their value from this, so a tag is validated in one place.
pub(crate) enum Cell {
    Str(String),
    Int(JsInt),
    Float(JsFloat, Option<JsDecimals>),
    Bool(bool),
    Null,
}

impl JsToonValue {
    /// The checked cell. A payload without its tag, an unknown tag, or a tag without its payload is an error, so a
    /// misspelled `type` cannot silently drop a value.
    pub(crate) fn into_cell(self) -> napi::Result<Cell> {
        let missing = |tag: &str, field: &str| {
            napi::Error::from_reason(format!("ToonValue: type is \"{tag}\" but {field} is missing"))
        };
        match self.r#type.as_str() {
            "str" => self.str_val.map(Cell::Str).ok_or_else(|| missing("str", "strVal")),
            "int" => self.int_val.map(Cell::Int).ok_or_else(|| missing("int", "intVal")),
            "float" => {
                self.float_val.map(|f| Cell::Float(f, self.decimals_val)).ok_or_else(|| missing("float", "floatVal"))
            }
            "bool" => self.bool_val.map(Cell::Bool).ok_or_else(|| missing("bool", "boolVal")),
            "null" => Ok(Cell::Null),
            other => Err(napi::Error::from_reason(format!(
                "ToonValue: unknown type {other:?}: expected \"str\", \"int\", \"float\", \"bool\", or \"null\""
            ))),
        }
    }
}

impl From<Cell> for crate::toon::Value {
    /// A TOON table cell. `decimalsVal` does not apply to tables.
    fn from(cell: Cell) -> Self {
        match cell {
            Cell::Str(s) => Self::Str(s.into()),
            Cell::Int(n) => Self::Int(n.get()),
            Cell::Float(f, _) => Self::Float(f.get()),
            Cell::Bool(b) => Self::Bool(b),
            Cell::Null => Self::Null,
        }
    }
}

impl From<Cell> for crate::kv::KvValue {
    /// A KV line or status value. Without `decimalsVal` a float keeps the number exact: its shortest decimals, as
    /// `RecoveryHint` deserialization does, or `FULL_PRECISION` (never rounds) for a value below about 1e-254.
    fn from(cell: Cell) -> Self {
        match cell {
            Cell::Str(s) => Self::Text(s),
            Cell::Int(n) => Self::Int(n.get()),
            Cell::Float(f, decimals) => {
                let decimals = decimals.map_or_else(|| crate::kv::exact_decimals(f.get()), JsDecimals::get_u8);
                Self::Float(f.get(), decimals)
            }
            Cell::Bool(b) => Self::Bool(b),
            Cell::Null => Self::Missing,
        }
    }
}

/// UTF-8 bytes of the string in one cell (0 for other types).
pub(crate) fn cell_bytes(v: &JsToonValue) -> usize {
    v.str_val.as_ref().map_or(0, String::len)
}

/// What one cell costs a response that keeps it: the stored value plus its string. Every cell keeps a
/// [`crate::toon::Value`] whatever its type, so a table of numbers or nulls is not free.
pub(crate) fn cell_cost(v: &JsToonValue) -> usize {
    std::mem::size_of::<crate::toon::Value>().saturating_add(cell_bytes(v))
}

