/// The full calls with control characters, the worst escape, measured against the bound and V8's string limit. The
/// partial-success case holds both caps at once: a full 16 MiB of strings and over 9 MiB of structure.
#[test]
fn every_full_call_renders_within_the_bound_and_v8s_limit() {
    let u = '\u{1}';
    let cases = [
        ("pipeline", full_pipeline(u)),
        ("cut pipeline", full_cut_pipeline(u)),
        ("partial success", full_partial_success(u)),
        ("status", full_status(u)),
        ("kv items", full_kv(u)),
        ("items", full_items(u)),
        ("a million cells", million_cells()),
        ("error", full_error(u)),
    ];
    let both = cases[2].1.as_ref().expect("fits").held.sum();
    assert!(both.strings > input::MAX_INPUT_BYTES - 64 * 1024 && both.structure > 9 * 1024 * 1024, "{both:?}");
    let mut largest = 0;
    for (label, r) in cases {
        let r = r.expect("fits");
        let held = r.held.total();
        for (surface, out) in ["text", "json", "toCallToolResult"].into_iter().zip(output_sizes(&r)) {
            assert!(
                out <= input::MAX_OUTPUT_FACTOR * held + input::OUTPUT_ENVELOPE,
                "{label}, {surface}: {out} bytes for {held} held"
            );
            assert!(out < input::V8_MAX_STRING_LEN, "{label}, {surface}: {out} bytes");
            largest = largest.max(out);
        }
    }
    assert!(largest > 100 * 1024 * 1024, "the largest render is {largest} bytes: the cases are not at the caps");
}

